import{_ as e}from"./chunks/fms-feature.hCgpzHMJ.js";import{_ as t,o,c as r,a2 as d}from"./chunks/framework.CqGPl1zp.js";const i="/newx-doc/img/FMS%E8%B4%A2%E5%8A%A1%E7%AE%A1%E7%90%86/%E9%A6%96%E9%A1%B5/%E8%B4%A2%E5%8A%A1%E9%A6%96%E9%A1%B5.png",l="/newx-doc/img/FMS%E8%B4%A2%E5%8A%A1%E7%AE%A1%E7%90%86/%E7%A7%BB%E5%8A%A8%E7%AB%AF/%E5%B7%A5%E4%BD%9C%E5%8F%B0.png",c="/newx-doc/img/ad/zsxq_fms.png",s="/newx-doc/img/FMS%E8%B4%A2%E5%8A%A1%E7%AE%A1%E7%90%86/%E6%A6%82%E8%A7%88/%E6%A8%A1%E5%9D%97%E5%85%B3%E7%B3%BB.svg",E=JSON.parse('{"title":"FMS 演示","description":"","frontmatter":{},"headers":[],"relativePath":"fms-preview.md","filePath":"fms-preview.md","lastUpdated":null}'),n={name:"fms-preview.md"};function h(u,a,m,_,f,p){return o(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="fms-演示" tabindex="-1">FMS 演示 <a class="header-anchor" href="#fms-演示" aria-label="Permalink to &quot;FMS 演示&quot;">​</a></h1><h2 id="_1-演示地址" tabindex="-1">1. 演示地址 <a class="header-anchor" href="#_1-演示地址" aria-label="Permalink to &quot;1. 演示地址&quot;">​</a></h2><p>FMS（Financial Management System，财务管理系统）用于维护企业从建账、凭证到账簿、报表、结账的完整财务链路，以账套为核算主体，串联设置管理、凭证管理、账簿管理、报表管理、结账管理五大业务域。</p><h3 id="_1-1-fms-管理后台" tabindex="-1">1.1 FMS 管理后台 <a class="header-anchor" href="#_1-1-fms-管理后台" aria-label="Permalink to &quot;1.1 FMS 管理后台&quot;">​</a></h3><ul><li>演示地址：<a href="http://dashboard-vue3.yudao.iocoder.cn/" target="_blank" rel="noreferrer">http://dashboard-vue3.yudao.iocoder.cn/</a></li><li>菜单：&quot;财务管理&quot;下的「首页」「凭证管理」「账簿管理」「报表管理」「结账管理」「设置管理」</li><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-vue3</a> 的 <code>fms</code> 目录，基于 Vue3 + Element Plus 实现</li></ul><p>同一个后台账号可以加入多个账套，通过页面顶部的账套切换器选择当前账套；凭证、账簿、报表和结账等数据，都只在当前账套下查询和维护。</p><p><img src="'+i+'" alt="管理后台"></p><h3 id="_1-2-fms-后端" tabindex="-1">1.2 FMS 后端 <a class="header-anchor" href="#_1-2-fms-后端" aria-label="Permalink to &quot;1.2 FMS 后端&quot;">​</a></h3><p>支持 Spring Boot 单体、Spring Cloud 微服务架构</p><ul><li>单体仓库：<a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://github.com/YunaiV/ruoyi-vue-pro</a> 的 <code>yudao-module-fms</code> 模块</li><li>微服务仓库：<a href="https://github.com/YunaiV/yudao-cloud" target="_blank" rel="noreferrer">https://github.com/YunaiV/yudao-cloud</a> 的 <code>yudao-module-fms</code> 服务</li></ul><h3 id="_1-3-fms-移动端" tabindex="-1">1.3 FMS 移动端 <a class="header-anchor" href="#_1-3-fms-移动端" aria-label="Permalink to &quot;1.3 FMS 移动端&quot;">​</a></h3><p>FMS 提供 uni-app 移动端，凭证、账簿、报表、结账和设置都可以在手机上处理，详见 <a href="./fms/mobile">《移动端 FMS》</a>。</p><ul><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-uniapp</a> 的 <code>pages-fms</code> 目录</li></ul><p><img src="'+l+'" alt="移动端"></p><h2 id="_2-fms-启动" tabindex="-1">2. FMS 启动 <a class="header-anchor" href="#_2-fms-启动" aria-label="Permalink to &quot;2. FMS 启动&quot;">​</a></h2><p>参见 <a href="./fms/build">《FMS 手册 —— 功能开启》</a> 文档，一般 3 分钟就可以启动完成。</p><h2 id="_3-fms-交流" tabindex="-1">3. FMS 交流 <a class="header-anchor" href="#_3-fms-交流" aria-label="Permalink to &quot;3. FMS 交流&quot;">​</a></h2><p>专属交流社区，欢迎扫码加入。</p><p><img src="'+c+'" alt="交流群"></p><h2 id="_4-功能描述" tabindex="-1">4. 功能描述 <a class="header-anchor" href="#_4-功能描述" aria-label="Permalink to &quot;4. 功能描述&quot;">​</a></h2><p>主要分为 5 个业务域：设置管理、凭证管理、账簿管理、报表管理、结账管理，另外提供财务首页汇总当前账套的核心指标。</p><p>业务以账套为中心：账套完成初始化后，依次维护币别、辅助核算、科目和初始余额，再录入并审核凭证；账簿实时读取初始余额和凭证分录，报表按期间保存公式快照及人工调整数据并实时计算金额，最后完成损益结转和期末结账。</p><p><img src="'+e+'" alt="FMS 功能列表"></p><h2 id="_5-表结构" tabindex="-1">5. 表结构 <a class="header-anchor" href="#_5-表结构" aria-label="Permalink to &quot;5. 表结构&quot;">​</a></h2><p>FMS 共 <strong>30</strong> 张表，表名统一以 <code>fms_</code> 为前缀。</p><p><img src="'+s+'" alt="FMS 全表关系"></p><table tabindex="0"><thead><tr><th>模块</th><th>子前缀</th><th>表数量</th><th>核心职责</th></tr></thead><tbody><tr><td>设置管理</td><td><code>fms_account_*</code>、<code>fms_finance_*</code>、<code>fms_currency</code>、<code>fms_subject*</code>、<code>fms_auxiliary_*</code>、<code>fms_assist_combination</code>、<code>fms_initial_balance</code>、<code>fms_voucher_word</code>、<code>fms_digest</code>、<code>fms_voucher_template*</code></td><td>15</td><td>账套、财务参数、指标、币别、科目、辅助核算、初始余额、凭证字、摘要和模板</td></tr><tr><td>凭证管理</td><td><code>fms_voucher</code>、<code>fms_voucher_entry</code></td><td>2</td><td>凭证主表和凭证分录</td></tr><tr><td>账簿管理</td><td>—</td><td>0</td><td>根据初始余额与凭证分录实时查询，不建独立账簿表</td></tr><tr><td>报表管理</td><td><code>fms_report_template</code>、<code>fms_balance_sheet_*</code>、<code>fms_income_statement_*</code>、<code>fms_cash_flow_*</code></td><td>9</td><td>三大财务报表的配置、期间结果和现金流辅助数据</td></tr><tr><td>结账管理</td><td><code>fms_closing*</code></td><td>4</td><td>结账方案、结账模板、结转凭证和会计期间状态</td></tr></tbody></table><h3 id="_5-1-设置管理" tabindex="-1">5.1 设置管理 <a class="header-anchor" href="#_5-1-设置管理" aria-label="Permalink to &quot;5.1 设置管理&quot;">​</a></h3><p>账套是 FMS 的核算主体，一个后台账号可以加入多个账套。账套初始化时确定本位币、启用期间、会计制度、科目级次和账簿余额方向；首页指标配置决定首页展示哪些指标及其取数公式。</p><p>核算基础按「<strong>币别 → 辅助核算 → 会计科目 → 财务初始余额</strong>」组织：币别提供本位币和外币资料，科目绑定辅助核算、外币和数量核算，初始余额保存启用期间的科目余额和辅助明细。</p><p>凭证字决定凭证编号和打印标题，常用摘要用于快速填写分录摘要，凭证模板用于保存和套用常见借贷分录。它们不参与建账，只服务于「录凭证」页面。</p><ul><li><a href="./fms/config/account-set">《【设置】账套管理、财务参数、财务指标》</a></li><li><a href="./fms/config/accounting">《【设置】币别、科目、辅助核算、初始余额》</a></li><li><a href="./fms/config/voucher">《【设置】凭证字、常用摘要、凭证模板》</a></li></ul><h3 id="_5-2-凭证管理" tabindex="-1">5.2 凭证管理 <a class="header-anchor" href="#_5-2-凭证管理" aria-label="Permalink to &quot;5.2 凭证管理&quot;">​</a></h3><p>围绕「<strong>录凭证 → 查凭证 → 审核 → 凭证汇总</strong>」形成日常账务闭环，并提供附件、导入、打印、移动和整理能力。</p><ul><li><a href="./fms/voucher">《【凭证】凭证管理》</a></li></ul><h3 id="_5-3-账簿管理" tabindex="-1">5.3 账簿管理 <a class="header-anchor" href="#_5-3-账簿管理" aria-label="Permalink to &quot;5.3 账簿管理&quot;">​</a></h3><p>明细账、总账、科目余额表、多栏账、核算项目账和数量金额账，均根据初始余额与凭证分录<strong>实时查询</strong>，不建立独立账簿表。</p><ul><li><a href="./fms/ledger">《【账簿】账簿管理》</a></li></ul><h3 id="_5-4-报表管理" tabindex="-1">5.4 报表管理 <a class="header-anchor" href="#_5-4-报表管理" aria-label="Permalink to &quot;5.4 报表管理&quot;">​</a></h3><p>资产负债表、利润表和现金流量表按期间生成，支持公式修改、勾稽检查、导出和打印；现金流量表另外提供辅助数据调整。</p><ul><li><a href="./fms/report">《【报表】财务报表》</a></li></ul><h3 id="_5-5-结账管理" tabindex="-1">5.5 结账管理 <a class="header-anchor" href="#_5-5-结账管理" aria-label="Permalink to &quot;5.5 结账管理&quot;">​</a></h3><p>结账前检查待审核凭证、初始余额、凭证号、损益结转和财务报表；检查通过后关闭当前期间，发现错误时按会计期间倒序反结账。</p><ul><li><a href="./fms/closing">《【结账】期末结账》</a></li></ul>',44)])])}const A=t(n,[["render",h]]);export{E as __pageData,A as default};
